import json,collections
rows=[json.loads(l) for l in open('samples.jsonl')]
by=collections.defaultdict(list)
for r in rows: by[r['task']].append(r)
for t,v in by.items():
    wrong=[r for r in v if not r['was_correct']]
    print(t, len(v), 'wrong', len(wrong))
    # group by example
    per=collections.defaultdict(list)
    for r in wrong: per[r['example_index']].append(r)
    print(' wrong examples:', len(per))
    for e,rs in sorted(per.items()):
        for r in rs:
            print('  ex%04d/%d %r -> %r  repair=%s'%(e,r['sample_index'],r['prediction'][:60],r['target'][:60],r.get('repair_turns')))
"

