import answer_conventions as ac
run='cd1bd0d40a39e7f9807fa0f12a58902c73abec2d'
mem=json.load(open(f'/workspace/runs/{run}/LawBench/memory.json')); prof=mem['answer_profile']
answers=prof['answers']; inventory=prof['items']
# refined classification
semi_units=set(); other_units=set()
for a in answers:
    first=next((c for c in ac.ITEM_SEPARATORS if c in a), None)
    for u in ac.split_items(a):
        if first==';': semi_units.add(u)
        else: other_units.add(u)
known_units = set(answers) | semi_units
fragments = {u for u in inventory if u not in known_units}
print('known units:', len(known_units), 'fragments:', len(fragments))
for probe in ['拐卖妇女','儿童','侮辱','生产','销售伪劣产品','盗窃','运输','窝藏','拐骗儿童','非法采伐、毁坏国家重点保护植物','虚开增值税专用发票、用于骗取出口退税、抵扣税款发票']:
    print('   %-30s in_answers=%s semi_unit=%s fragment=%s'%(probe, probe in answers, probe in semi_units, probe in fragments))
# val targets: any fragment item?
rows=[json.loads(l) for l in open(f'/workspace/runs/{run}/results/samples.jsonl') if json.loads(l)['task']=='LawBench']
tgts={}
for r in rows: tgts[r['example_index']]=r['target']
bad=[]
for ex,t in sorted(tgts.items()):
    items=ac.split_items(t)
    fr=[i for i in items if i in fragments]
    if fr: bad.append((ex,t,fr))
print('val questions whose target has a fragment item:', len(bad))
for b in bad: print('   ', b)
